export function getGiLoadoutsWeaponIcon(name: string): string | undefined {
  const key = name.toLowerCase().replace(/[^a-z0-9]/g, "");
  const path = GI_LOADOUTS_WEAPON_ICONS[key];
  return path ? GI_LOADOUTS_WEAPON_BASE + path : undefined;
}
